add_action( 'woocommerce_after_shop_loop_item', 'perfectpixel_dimensions_in_loop', 7 );

function perfectpixel_dimensions_in_loop() {
	global $product;
	if ( ! $product ) {
		return;
	}
	$lines = array();
	if ( $product->has_dimensions() ) {
		$lines[] = esc_html( '{{loop_dimensions_label}}' ) . ' ' . esc_html( wc_format_dimensions( $product->get_dimensions( false ) ) );
	}
	$weight_label = trim( '{{loop_weight_label}}' );
	if ( '' !== $weight_label && $product->has_weight() ) {
		$lines[] = esc_html( $weight_label ) . ' ' . esc_html( wc_format_weight( $product->get_weight() ) );
	}
	if ( $lines ) {
		echo '<div class="perfectpixel-loop-dimensions" style="font-size:.85em;margin:.5em 0">' . implode( '<br>', $lines ) . '</div>';
	}
}
